srcDoc.css:
body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: transparent;
  color: #111827;
}

.charts {
  padding: 0 22px 22px;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 12px;
  box-sizing: border-box;
}

.panel {
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  background: #fff;
  padding: 14px;
  min-height: 240px;
}

.head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 14px;
}

.head span {
  display: block;
  color: #667085;
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 900;
}

.head h2 {
  margin: 3px 0 0;
  font-size: 18px;
}

.head b {
  font-size: 12px;
  color: #667085;
}

.bars {
  height: 170px;
  display: flex;
  align-items: flex-end;
  gap: 8px;
  border-bottom: 1px solid #d0d5dd;
  padding-top: 14px;
}

.bar-wrap {
  flex: 1;
  min-width: 0;
  text-align: center;
}

.bar {
  width: 100%;
  min-height: 4px;
  border-radius: 6px 6px 0 0;
  background: #111827;
}

.bar-label {
  margin-top: 7px;
  color: #667085;
  font-size: 10px;
  white-space: nowrap;
}

.list {
  display: grid;
  gap: 8px;
}

.row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  align-items: center;
  border: 1px solid #eaecf0;
  border-radius: 8px;
  padding: 10px;
}

.row span {
  font-size: 13px;
  font-weight: 800;
}

.row b {
  font-size: 13px;
}

.empty {
  color: #667085;
  font-size: 13px;
  padding: 18px;
  text-align: center;
  border: 1px dashed #d0d5dd;
  border-radius: 8px;
}

@media (max-width: 1100px) {
  .charts {
    grid-template-columns: 1fr;
  }
}

srcDoc.js:
function money(value) {
  return Number(value || 0).toFixed(2);
}
function shortDate(value) {
  if (!value) return "";
  const d = new Date(value);
  return `${d.getDate()}.${d.getMonth() + 1}.`;
}
function renderSalesTrend(rows = []) {
  const max = Math.max(...rows.map(row => Number(row.totalSales || 0)), 1);
  document.getElementById("salesChart").innerHTML = rows.length ? rows.map(row => {
    const value = Number(row.totalSales || 0);
    const height = Math.max(value / max * 150, 4);
    return `
        <div class="bar-wrap" title="${money(value)}">
          <div class="bar" style="height:${height}px"></div>
          <div class="bar-label">${shortDate(row.salesDate)}</div>
        </div>
      `;
  }).join("") : `<div class="empty">No sales data.</div>`;
}
function renderList(id, rows = [], labelKey, valueKey, suffix = "") {
  document.getElementById(id).innerHTML = rows.length ? rows.map(row => `
      <div class="row">
        <span>${row[labelKey] || "-"}</span>
        <b>${money(row[valueKey])}${suffix}</b>
      </div>
    `).join("") : `<div class="empty">No data.</div>`;
}
function render(model = {}) {
  renderSalesTrend(model.salesTrend || []);
  renderList("paymentMix", model.paymentMix || [], "paymentMethod", "totalAmount", " EUR");
  document.getElementById("fiscalStatus").innerHTML = (model.fiscalStatus || []).length ? (model.fiscalStatus || []).map(row => `
      <div class="row">
        <span>${row.fiscalStatus || "NOT_FISCALIZED"}</span>
        <b>${row.countDocs || 0}</b>
      </div>
    `).join("") : `<div class="empty">No fiscal data.</div>`;
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

